// Operation input/output schema bodies. Public bodies must remain canonically
// equal to the frozen catalog entries; internal bodies mirror the exact
// schemas in the implementation assignment.
const (
	schemaCandidateIn     = `{"type":"object","additionalProperties":false,"properties":{"candidate":{"$ref":"#/$defs/Candidate"}},"required":["candidate"]}`
	schemaValidateOut     = `{"type":"object","additionalProperties":false,"properties":{"resource":{"$ref":"#/$defs/Validation"}},"required":["resource"]}`
	schemaActivateOut     = `{"type":"object","additionalProperties":false,"properties":{"versions":{"type":"array","items":{"$ref":"#/$defs/Ref"},"maxItems":4096}},"required":["versions"]}`
	schemaScopeIn         = `{"type":"object","additionalProperties":false,"properties":{"scope":{"$ref":"#/$defs/Scope"}},"required":["scope"]}`
	schemaInspectOut      = `{"type":"object","additionalProperties":false,"properties":{"limits":{"$ref":"#/$defs/Limits"},"usage":{"$ref":"#/$defs/Usage"}},"required":["limits","usage"]}`
	schemaReserveIn       = `{"type":"object","additionalProperties":false,"properties":{"scope":{"$ref":"#/$defs/Scope"},"root_task_id":{"type":"string","format":"uuid"},"operation_id":{"type":"string","format":"uuid"},"amount":{"$ref":"#/$defs/Money"},"limits":{"$ref":"#/$defs/Limits"}},"required":["scope","operation_id","amount","limits"]}`
	schemaReservationOut  = `{"type":"object","additionalProperties":false,"properties":{"resource":{"$ref":"#/$defs/Reservation"}},"required":["resource"]}`
	schemaSettleIn        = `{"type":"object","additionalProperties":false,"properties":{"reservation_id":{"type":"string","format":"uuid"},"expected_version":{"type":"integer","minimum":1,"maximum":9223372036854775807},"usage":{"$ref":"#/$defs/Usage"},"authoritative_nonexecution":{"type":"boolean"}},"required":["reservation_id","expected_version","usage","authoritative_nonexecution"]}`
	schemaBudgetGetIn     = `{"type":"object","additionalProperties":false,"properties":{"scope":{"$ref":"#/$defs/Scope"}},"required":["scope"]}`
	schemaBudgetGetOut    = `{"type":"object","additionalProperties":false,"properties":{"limits":{"$ref":"#/$defs/Limits"}},"required":["limits"]}`
	schemaBudgetProposeIn = `{"type":"object","additionalProperties":false,"properties":{"scope":{"$ref":"#/$defs/Scope"},"expected_version":{"type":"integer","minimum":1,"maximum":9223372036854775807},"limits":{"$ref":"#/$defs/Limits"},"draft_id":{"type":"string","format":"uuid"}},"required":["scope","expected_version","limits"]}`
	schemaDraftOut        = `{"type":"object","additionalProperties":false,"properties":{"resource":{"$ref":"#/$defs/Draft"}},"required":["resource"]}`
	schemaUsageGetIn      = `{"type":"object","additionalProperties":false,"properties":{"scope":{"$ref":"#/$defs/Scope"}},"required":["scope"]}`
	schemaUsageGetOut     = `{"type":"object","additionalProperties":false,"properties":{"resource":{"$ref":"#/$defs/Usage"}},"required":["resource"]}`
)

// wireSchema holds one operation's merged input and output documents.
type wireSchema struct {
	Input  string
	Output string
}

// wireSchemas merges every operation body with the shared $defs document.
var wireSchemas = map[string]wireSchema{
	"_accounting.activate": {schemaCandidateIn, schemaActivateOut},
	"_accounting.inspect":  {schemaScopeIn, schemaInspectOut},
	"_accounting.reserve":  {schemaReserveIn, schemaReservationOut},
	"_accounting.settle":   {schemaSettleIn, schemaReservationOut},
	"_accounting.validate": {schemaCandidateIn, schemaValidateOut},
	"budget.get":           {schemaBudgetGetIn, schemaBudgetGetOut},
	"budget.propose":       {schemaBudgetProposeIn, schemaDraftOut},
	"usage.get":            {schemaUsageGetIn, schemaUsageGetOut},
}

// mergeSchema splices an operation schema body into the shared $defs
// document, producing one schema document whose document-local $refs resolve
// against the exact brief definitions.
func mergeSchema(body string) (json.RawMessage, error) {
	if len(body) < 2 || body[0] != '{' || body[len(body)-1] != '}' {
		return nil, fmt.Errorf("schema body is not a JSON object")
	}
	defsLen := len(wireDefs)
	if defsLen < 2 || wireDefs[defsLen-1] != '}' {
		return nil, fmt.Errorf("embedded $defs document is malformed")
	}
	merged := wireDefs[:defsLen-1] + "," + body[1:]
	return json.RawMessage(merged), nil
}
